/**
 * Plugin lifecycle hooks: allows plugins to tap into webcmd's execution lifecycle.
 *
 * Hooks use globalThis (like the command registry) to guarantee a single shared
 * instance across all module copies — critical when TS plugins are loaded via
 * npm link / peerDependency symlinks.
 *
 * Available hooks:
 *   onStartup        — fired once after all commands & plugins are discovered
 *   onBeforeExecute  — fired before every command execution
 *   onAfterExecute   — fired after every command execution (receives result)
 */
import { log } from './logger.js';
const _hooks = globalThis.__webcmd_hooks__ ??= new Map();
// ── Registration API (used by plugins) ─────────────────────────────────────
function addHook(name, fn) {
    const list = _hooks.get(name) ?? [];
    if (list.includes(fn))
        return;
    list.push(fn);
    _hooks.set(name, list);
}
/** Register a hook that fires once after all plugins are discovered. */
export function onStartup(fn) {
    addHook('onStartup', fn);
}
/** Register a hook that fires before every command execution. */
export function onBeforeExecute(fn) {
    addHook('onBeforeExecute', fn);
}
/** Register a hook that fires after every command execution with the result. */
export function onAfterExecute(fn) {
    addHook('onAfterExecute', fn);
}
// ── Emit API (used internally by webcmd core) ─────────────────────────────
/**
 * Trigger all registered handlers for a hook.
 * Each handler is wrapped in try/catch — a failing hook never blocks command execution.
 */
export async function emitHook(name, ctx, result) {
    const handlers = _hooks.get(name);
    if (!handlers || handlers.length === 0)
        return;
    for (const fn of handlers) {
        try {
            await fn(ctx, result);
        }
        catch (err) {
            log.warn(`Hook ${name} handler failed: ${err instanceof Error ? err.message : String(err)}`);
        }
    }
}
export const WEBCMD_ROOT_COMMANDS = new Set([
    'adapter',
    'auth',
    'browser',
    'completion',
    'convention-audit',
    'daemon',
    'doctor',
    'external',
    'list',
    'plugin',
    'profile',
    'session',
    'site',
    'skills',
    'update',
    'validate',
    'verify',
    'web',
]);
export function shouldRunStartupSideEffects(argv) {
    if (isHelp(argv))
        return false;
    return !(hasExplicitOutputFormat(argv) && WEBCMD_ROOT_COMMANDS.has(rootCommand(argv) ?? ''));
}
export function shouldEnsureUserCliCompatShims(argv) {
    return shouldRunStartupSideEffects(argv) || (!isHelp(argv) && rootCommand(argv) === 'auth');
}
export function shouldEmitStartupHook(argv) {
    return !isHelp(argv) && !isCompletion(argv);
}
function isHelp(argv) {
    for (const token of argv) {
        if (token === '--')
            return false;
        if (token === '--help' || token === '-h')
            return true;
    }
    return false;
}
function isCompletion(argv) {
    return argv.includes('--get-completions');
}
function hasExplicitOutputFormat(argv) {
    for (let i = 0; i < argv.length; i += 1) {
        const token = argv[i];
        if (token === '--')
            return false;
        if (token === '--json')
            return true;
        if (token === '-f' || token === '--format' || /^-f.+/.test(token) || token.startsWith('--format='))
            return true;
    }
    return false;
}
function rootCommand(argv) {
    for (let i = 0; i < argv.length; i += 1) {
        const token = argv[i];
        if (token === '--')
            return argv[i + 1];
        if (token === '--profile' || token === '--session' || token === '--workspace') {
            i += 1;
            continue;
        }
        if (token.startsWith('--profile=') || token.startsWith('--session=') || token.startsWith('--workspace='))
            continue;
        if (!token.startsWith('-') || token === '-')
            return token;
    }
    return undefined;
}
/**
 * Remove all registered hooks. Intended for testing only.
 */
export function clearAllHooks() {
    _hooks.clear();
}
